import type { InventoryCategory } from "../types/inventory.js";

export interface FoodCategoryEntry {
    name: string;
    category: InventoryCategory;
}

export interface FoodCategoryKeywordHint {
    keyword: string;
    category: InventoryCategory;
    order: number;
}

// One-time seed data for the `foodCategories` / `foodCategoryKeywords` Mongo collections.
// Only imported by foodCategory.model.ts's ensureSeeded(), which inserts this the first time
// either collection is empty — the running app otherwise reads from Mongo, not from here.
//
// FOOD_CATEGORY_SEED is a merge of a hand-curated common-grocery-item list with Health
