// Canada, https://open.canada.ca/data/en/dataset/1b6139bd-ed7e-4043-bc28-ff00e10f3109),
// mapped from CNF's 24 food groups onto this app's 16 categories. On name collisions the
// hand-curated mapping wins over CNF's.
